inp('title','Event title',$e['title']??'');inp('genre','Event type',$e['genre']??'');inp('venue','Venue',$e['venue']??'');inp('starts','Start time (Sri Lanka)',isset($e['starts'])?substr(str_replace(' ','T',$e['starts']),0,16):'','datetime-local');?>
